require_once dirname(__DIR__).'/private/operations.php';
require_once dirname(__DIR__).'/private/waste_connections.php';
$operations=opsReady($pdo);$error=$_SESSION['property_error']??'';$notice=$_SESSION['property_notice']??'';unset($_SESSION['property_error'],$_SESSION['property_notice']);
