  else{$s=$pdo->prepare("UPDATE recurring_jobs SET active=1-active WHERE id=? AND property_id=? AND rule_source<>'routine_unverified'");$s->execute([(int)($_POST['rule_id']??0),$id]);if(!$s->rowCount())throw new RuntimeException('Diese Regel lässt sich hier nicht pausieren.');}
 }catch(Throwable $e){$_SESSION['property_error']=$e instanceof PDOException?'Speichern nicht möglich.':$e->getMessage();}redirect('property.php?id='.$id.'#regelmaessig');}
 if($operations){try{if($action==='update')opsSaveProperty($pdo,(int)$_SESSION['admin_id'],$id,$_POST);elseif($action==='toggle')opsSetDone($pdo,(int)$_SESSION['admin_id'],(int)($_POST['task_id']??0),($_POST['done']??'')==='1',opsVersion($_POST),$id);elseif($action==='task'){$title=opsText($_POST,'title',190,true);$date=(string)($_POST['due_date']??'');if($date!==''&&!zgsValidDate($date))throw new RuntimeException('Datum ungültig.');opsSaveTask($pdo,(int)$_SESSION['admin_id'],[$title,$date?:null,'',null,null,'normal',0,null,null],$id,0,false,null);}else throw new RuntimeException('Aktion unbekannt.');require_once dirname(__DIR__).'/private/planning_store.php';gszSuggestWeek($pdo,(int)$_SESSION['admin_id']);}catch(Throwable $e){$_SESSION['property_error']=$e instanceof PDOException?'Datenbank nicht bereit.':$e->getMessage();}redirect('property.php?id='.$id);}
 if($action==='update'){
  $name=trim((string)($_POST['name']??''));$address=trim((string)($_POST['address']??''));
  $contact=trim((string)($_POST['contact_name']??''));$phone=trim((string)($_POST['contact_phone']??''));
  $email=trim((string)($_POST['contact_email']??''));$notes=trim((string)($_POST['notes']??''));
  if($name===''||mb_strlen($name)>190||mb_strlen($address)>255||mb_strlen($contact)>190||mb_strlen($phone)>80||mb_strlen($email)>190||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||mb_strlen($notes)>5000){$error='Bitte Eingaben pruefen.';}
  else{$st=$pdo->prepare('UPDATE properties SET name=?,address=?,contact_name=?,contact_phone=?,contact_email=?,notes=? WHERE id=?');$st->execute([$name,$address,$contact,$phone,$email,$notes,$id]);redirect('property.php?id='.$id);}
 }elseif($action==='task'){
  $title=trim((string)($_POST['title']??''));$date=(string)($_POST['due_date']??'');
  $validDate=$date===''|| (preg_match('/^\d{4}-\d{2}-\d{2}$/',$date) && DateTimeImmutable::createFromFormat('!Y-m-d',$date)?->format('Y-m-d')===$date);
  if($title===''||mb_strlen($title)>190||!$validDate){$error='Aufgabe oder Datum ungueltig.';}
  else{$st=$pdo->prepare('INSERT INTO tasks(property_id,title,due_date) VALUES(?,?,?)');$st->execute([$id,$title,$date?:null]);redirect('property.php?id='.$id);}
 }elseif($action==='toggle'){
  $st=$pdo->prepare('UPDATE tasks SET done=1-done WHERE id=? AND property_id=?');$st->execute([(int)($_POST['task_id']??0),$id]);redirect('property.php?id='.$id);
 }
}
$st=$pdo->prepare('SELECT * FROM tasks WHERE property_id=? ORDER BY done ASC,due_date ASC,id DESC LIMIT 200');$st->execute([$id]);$tasks=$st->fetchAll();
$st=$pdo->prepare('SELECT * FROM recurring_jobs WHERE property_id=? ORDER BY active DESC,id DESC LIMIT 100');$st->execute([$id]);$jobs=$st->fetchAll();
$customers=$operations?$pdo->query('SELECT id,name,archived_at FROM customers ORDER BY name LIMIT 2000')->fetchAll():[];
$history=$operations?opsHistory($pdo,'property',$id):[];
$freq=['weekly'=>'Woechentlich','biweekly'=>'Alle 2 Wochen','monthly'=>'Monatlich','quarterly'=>'Vierteljaehrlich','seasonal'=>'Saisonal'];
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=e($p['name'])?></title></head><body><main><p><a href="objects.php">‹ Objekte</a></p><div class="page-head"><div><h1><?=e($p['name'])?></h1><p class="sub"><?=e($p['address'])?><?=!empty($p['customer_name'])?' · '.e($p['customer_name']):''?></p></div></div><?php if($p['address']!==''):?><p><a href="https://maps.apple.com/?q=<?=e(rawurlencode($p['address']))?>" target="_blank" rel="noopener noreferrer">Route in Karten öffnen</a> · <a href="worklogs.php?property_id=<?=$id?>">Arbeitsnachweise</a></p><?php endif?><?php if($error):?><p class="error" role="alert"><?=e($error)?></p><?php endif?><?php if($notice):?><p class="notice flash" role="status"><?=e($notice)?></p><?php endif?><?php if(wasteAutoReady($pdo)):$connection=wasteConnection($pdo,(int)$id);?><section class="card"><h2>Abfallkalender</h2><p><?=e($connection?wasteConnectionStatus($connection):'Noch nicht eingerichtet')?></p><p><a href="waste_setup.php?id=<?=$id?>">Mülltonnenservice, betreute Tonnen und offizielle Kalender einrichten</a></p></section><?php endif?><div class="grid"><details class="card"><summary>Objektdaten und Ansprechpartner</summary><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="update"><?php if($operations):?><input type="hidden" name="row_version" value="<?=(int)$p['row_version']?>"><label>Kundenzuordnung<select name="customer_id"><option value="0">Ohne Zuordnung</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>" <?=(int)$p['customer_id']===(int)$c['id']?'selected':''?>><?=e($c['name'])?><?=empty($c['archived_at'])?'':' (archiviert)'?></option><?php endforeach?></select></label><?php endif?><label>Objektbezeichnung<input name="name" maxlength="190" value="<?=e($p['name'])?>" required></label><label>Adresse<input name="address" maxlength="255" value="<?=e($p['address'])?>"></label><label>Ansprechpartner<input name="contact_name" maxlength="190" value="<?=e($p['contact_name'])?>"></label><label>Telefon<input name="contact_phone" maxlength="80" type="tel" value="<?=e($p['contact_phone'])?>"></label><label>E-Mail<input name="contact_email" maxlength="190" type="email" value="<?=e($p['contact_email'])?>"></label><label>Objekthinweise<textarea name="notes" maxlength="5000" rows="5"><?=e($p['notes'])?></textarea></label><?php if(gszV1Ready($pdo)):?><label>Tonnen raus: Tage gegenüber Leerung (−1 = Vortag)<input type="number" name="waste_out_offset" min="-3" max="0" value="<?=(int)($p['waste_out_offset']??-1)?>"></label><label>Tonnen rein: Tage nach Leerung (0 = Abfuhrtag)<input type="number" name="waste_in_offset" min="0" max="3" value="<?=(int)($p['waste_in_offset']??0)?>"></label><p>Gilt für neu angelegte bestätigte Kalenderaufgaben. Bereits erledigte/manuell korrigierte Aufgaben werden nicht still verändert.</p><?php endif?><button>Objektdaten speichern</button></form><?php if($p['contact_phone']):?><p><a href="tel:<?=e(preg_replace('/[^0-9+]/','',$p['contact_phone']))?>">Ansprechpartner anrufen</a></p><?php endif?></details><section class="card"><h2>Aufgaben</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="task"><label>Neue Aufgabe<input name="title" maxlength="190" placeholder="z. B. Tiefgarage kontrollieren" required></label><label>Fällig am<input name="due_date" type="date"></label><button>Aufgabe hinzufügen</button></form><?php if(!$tasks):?><p class="muted">Noch keine Aufgaben fuer dieses Objekt.</p><?php endif?><?php foreach($tasks as $t):?><div class="item"><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="task_id" value="<?=$t['id']?>"><?php if($operations):?><input type="hidden" name="done" value="<?=$t['done']?'0':'1'?>"><input type="hidden" name="row_version" value="<?=(int)$t['row_version']?>"><?php endif?><button class="ghost" aria-label="Status wechseln"><?=$t['done']?'↩':'✓'?></button></form> <span class="<?=$t['done']?'done':''?>"><?=e($t['title'])?></span><div class="muted"><?=e($t['due_date'])?></div><?php if($operations):?><a href="task.php?id=<?=(int)$t['id']?>">Notiz / Zuordnung / Verlauf</a><?php endif?></div><?php endforeach?></section><section class="card" id="regelmaessig"><h2>Regelmäßige Arbeiten</h2><?php require_once dirname(__DIR__).'/private/recurring_quick.php';$wd=['','Mo','Di','Mi','Do','Fr','Sa','So'];?>
<?php if(!$jobs):?><p class="muted">Noch keine regelmäßigen Arbeiten – z. B. Treppenhausreinigung wöchentlich.</p><?php else:?><div class="list"><?php foreach($jobs as $j):$next=$j['next_due_date']?new DateTimeImmutable($j['next_due_date']):null;?><div class="li"><span class="name"><?=e($j['title'])?><span class="sub"><?=e(GSZ_QUICK_FREQ[$j['frequency']]??($j['frequency']==='seasonal'?'nach Bedarf':$j['frequency']))?><?=$j['active']&&$next?' · nächstes Mal '.e($wd[(int)$next->format('N')].', '.$next->format('d.m.')):''?><?=$j['duration_minutes']?' · '.(int)$j['duration_minutes'].' Min.':''?><?=$j['active']?'':' · pausiert'?></span></span><?php if($j['rule_source']!=='routine_unverified'):?><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="rule_toggle"><input type="hidden" name="rule_id" value="<?=(int)$j['id']?>"><button class="small"><?=$j['active']?'Pausieren':'Fortsetzen'?></button></form><?php endif?></div><?php endforeach?></div><?php endif?>
<details class="sub"<?=$jobs?'':' open'?>><summary>Regelmäßige Arbeit hinzufügen</summary><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="rule_add">
