 <button class="primary">Hinzufügen</button></form></details></section></div><?php require_once dirname(__DIR__).'/private/dashboard_service.php';gszObjectPanel($pdo,(int)$id);?><?php if($history):?><section class="card"><h2>Änderungshistorie</h2><?php foreach($history as $h):?><details><summary><?=e($h['created_at'].' UTC · '.$h['action'])?></summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e($h['changes_json'])?></pre></details><?php endforeach?></section><?php endif?></main></body></html>
